"""Core data models for the metadata-aware RAG system."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from enum import Enum
from typing import Any, Dict, Iterable, List, Optional

_MISSING = object()


class FilterOperator(str, Enum):
    """Comparison operators supported by :class:`Condition`."""

    EQ = "eq"                # equality (case-insensitive for strings)
    NE = "ne"                # inequality
    GT = "gt"                # strictly greater
    GTE = "gte"              # greater or equal
    LT = "lt"                # strictly less
    LTE = "lte"              # less or equal
    IN = "in"                # value is in a collection
    NIN = "nin"              # value is not in a collection
    CONTAINS = "contains"    # substring match / list membership
    EXISTS = "exists"        # key present and non-empty


@dataclass
class Metadata:
    """Convenience structure describing a document's metadata.

    The pipeline itself works with plain ``dict`` objects (see
    :meth:`Metadata.as_dict`), so this class is optional sugar.
    """

    source: str = ""
    doc_id: str = ""
    title: str = ""
    category: str = ""
    author: str = ""
    created_at: Optional[datetime] = None
    importance: float = 0.5  # 0..1 authority/importance score
    tags: List[str] = field(default_factory=list)
    extra: Dict[str, Any] = field(default_factory=dict)

    def as_dict(self) -> Dict[str, Any]:
        d: Dict[str, Any] = {
            "source": self.source,
            "doc_id": self.doc_id,
            "title": self.title,
            "category": self.category,
            "author": self.author,
            "importance": self.importance,
            "tags": list(self.tags),
        }
        if self.created_at is not None:
            d["created_at"] = self.created_at.isoformat()
        d.update(self.extra)
        return d

    def get(self, key: str, default: Any = None) -> Any:
        if hasattr(self, key):
            value = getattr(self, key)
            if value is not None:
                return value
        return self.extra.get(key, default)


@dataclass
class Condition:
    """A single metadata predicate, e.g. ``category == "finance"``."""

    key: str
    op: FilterOperator
    value: Any = None

    def matches(self, metadata: Dict[str, Any]) -> bool:
        actual = metadata.get(self.key, _MISSING)
        if actual is _MISSING or actual is None or actual == "":
            actual = None

        if self.op == FilterOperator.EXISTS:
            return actual is not None
        if actual is None:
            return False

        if self.op == FilterOperator.IN:
            return any(self._norm_eq(actual, item) for item in self._as_list(self.value))
        if self.op == FilterOperator.NIN:
            return not any(self._norm_eq(actual, item) for item in self._as_list(self.value))
        if self.op == FilterOperator.CONTAINS:
            if isinstance(actual, (list, tuple, set, frozenset)):
                return any(self._norm_eq(item, self.value) for item in actual)
            return self._norm_str(self.value) in self._norm_str(actual)

        a = self._normalize(actual)
        b = self._normalize(self.value)
        try:
            if self.op == FilterOperator.EQ:
                return self._norm_eq(actual, self.value)
            if self.op == FilterOperator.NE:
                return not self._norm_eq(actual, self.value)
            if self.op == FilterOperator.GT:
                return a > b
            if self.op == FilterOperator.GTE:
                return a >= b
            if self.op == FilterOperator.LT:
                return a < b
            if self.op == FilterOperator.LTE:
                return a <= b
        except TypeError:
            return False
        return False

    # ------------------------------------------------------------------ #
    # normalization helpers
    # ------------------------------------------------------------------ #
    @staticmethod
    def _normalize(value: Any) -> Any:
        """Coerce ISO date strings and aware datetimes to naive UTC datetimes."""
        if isinstance(value, str):
            text = value.strip()
            try:
                dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
            except ValueError:
                return value
            if dt.tzinfo is not None:
                dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
            return dt
        if isinstance(value, datetime):
            if value.tzinfo is not None:
                return value.astimezone(timezone.utc).replace(tzinfo=None)
            return value
        if isinstance(value, date):
            return datetime(value.year, value.month, value.day)
        return value

    @staticmethod
    def _norm_str(value: Any) -> str:
        return str(value).strip().lower()

    @classmethod
    def _norm_eq(cls, a: Any, b: Any) -> bool:
        a = cls._normalize(a)
        b = cls._normalize(b)
        if isinstance(a, datetime) and isinstance(b, datetime):
            return a == b
        if isinstance(a, str) and isinstance(b, str):
            return a.strip().lower() == b.strip().lower()
        try:
            return bool(a == b)
        except Exception:
            return str(a) == str(b)

    @staticmethod
    def _as_list(value: Any) -> List[Any]:
        if value is None:
            return []
        if isinstance(value, str):
            return [value]
        try:
            return list(value)
        except TypeError:
            return [value]

    def __str__(self) -> str:
        return f"{self.key} {self.op.value} {self.value}"


class MetadataFilter:
    """A collection of predicates combined with AND semantics.

    Supports both a flat list of conditions and optional OR groups::

        MetadataFilter([
            Condition("category", FilterOperator.EQ, "finance"),
        ], or_groups=[
            [Condition("source", FilterOperator.EQ, "A"),
             Condition("source", FilterOperator.EQ, "B")],
        ])
    """

    def __init__(
        self,
        conditions: Iterable[Condition] = (),
        or_groups: Iterable[Iterable[Condition]] = (),
    ) -> None:
        self.conditions: List[Condition] = list(conditions)
        self.or_groups: List[List[Condition]] = [list(g) for g in or_groups]

    @classmethod
    def from_dict(cls, spec: Dict[str, Any]) -> "MetadataFilter":
        """Build a filter from a compact dict spec.

        Examples::

            {"category": "finance"}                          # equality
            {"source": {"in": ["A", "B"]}}                   # operator form
            {"created_at": {"gte": "2024-01-01"}}            # date range
            {"author": None}                                 # must exist
        """
        conditions: List[Condition] = []
        for key, value in spec.items():
            if isinstance(value, dict) and len(value) == 1:
                op_name, operand = next(iter(value.items()))
                try:
                    op = FilterOperator(op_name)
                except ValueError:
                    raise ValueError(
                        f"Unknown operator {op_name!r} for key {key!r}; "
                        f"valid: {[op.value for op in FilterOperator]}"
                    ) from None
                conditions.append(Condition(key, op, operand))
            elif value is None:
                conditions.append(Condition(key, FilterOperator.EXISTS))
            else:
                conditions.append(Condition(key, FilterOperator.EQ, value))
        return cls(conditions)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        if not all(c.matches(metadata) for c in self.conditions):
            return False
        for group in self.or_groups:
            if not any(c.matches(metadata) for c in group):
                return False
        return True

    def empty(self) -> bool:
        return not (self.conditions or self.or_groups)

    def __bool__(self) -> bool:
        return not self.empty()

    def describe(self) -> str:
        parts = [str(c) for c in self.conditions]
        for group in self.or_groups:
            parts.append("(" + " OR ".join(str(c) for c in group) + ")")
        return "; ".join(parts) if parts else "no constraints"


@dataclass
class RetrievalResult:
    """A retrieved chunk with its metadata and ranking score."""

    text: str
    metadata: Dict[str, Any]
    score: float = 0.0
    doc_id: str = ""
    rank: int = 0
    embedding: Optional[List[float]] = None  # set for dense results (used by MMR)

    def __post_init__(self) -> None:
        if not self.doc_id:
            self.doc_id = str(self.metadata.get("doc_id", ""))

"""Okapi BM25 sparse retrieval with metadata pre-filtering."""

from __future__ import annotations

import math
from collections import Counter
from typing import Any, Dict, List, Optional, Sequence

from .embeddings import tokenize
from .models import MetadataFilter, RetrievalResult


class BM25Index:
    """Classic BM25 (k1=1.5, b=0.75) over tokenized chunks.

    Complements the dense vector store with exact keyword matching, which
    matters for domain-specific terms, IDs, and rare vocabulary.
    """

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self._texts: List[str] = []
        self._metadatas: List[Dict[str, Any]] = []
        self._doc_terms: List[Counter] = []
        self._doc_lens: List[int] = []
        self._avg_len: float = 0.0
        self._idf: Dict[str, float] = {}

    @property
    def size(self) -> int:
        return len(self._texts)

    def add_texts(
        self,
        texts: Sequence[str],
        metadatas: Optional[Sequence[Dict[str, Any]]] = None,
    ) -> int:
        if metadatas is None:
            metadatas = [{}] * len(texts)
        for text, meta in zip(texts, metadatas):
            terms = Counter(tokenize(text))
            self._texts.append(text)
            self._metadatas.append(dict(meta or {}))
            self._doc_terms.append(terms)
            self._doc_lens.append(sum(terms.values()))

        n_docs = len(self._texts)
        self._avg_len = sum(self._doc_lens) / n_docs if n_docs else 0.0
        df: Counter = Counter()
        for terms in self._doc_terms:
            df.update(terms.keys())
        self._idf = {
            term: math.log(1.0 + (n_docs - freq + 0.5) / (freq + 0.5))
            for term, freq in df.items()
        }
        return n_docs

    def search(
        self,
        query: str,
        k: int = 5,
        metadata_filter: Optional[MetadataFilter] = None,
    ) -> List[RetrievalResult]:
        q_terms = tokenize(query)
        if not q_terms:
            return []

        scored: List[tuple] = []
        for i, terms in enumerate(self._doc_terms):
            meta = self._metadatas[i]
            if metadata_filter and not metadata_filter.matches(meta):
                continue
            dl = self._doc_lens[i]
            score = 0.0
            for term in q_terms:
                tf = terms.get(term, 0)
                if tf == 0:
                    continue
                idf = self._idf.get(term, 0.0)
                if self._avg_len > 0.0:
                    denom = tf + self.k1 * (1.0 - self.b + self.b * dl / self._avg_len)
                else:
                    denom = 1.0
                score += idf * (tf * (self.k1 + 1.0)) / denom
            if score > 0.0:
                scored.append((score, i))

        scored.sort(key=lambda t: t[0], reverse=True)
        results: List[RetrievalResult] = []
        for rank, (score, idx) in enumerate(scored[:k]):
            meta = dict(self._metadatas[idx])
            results.append(
                RetrievalResult(
                    text=self._texts[idx],
                    metadata=meta,
                    score=float(score),
                    doc_id=str(meta.get("doc_id", idx)),
                    rank=rank,
                )
            )
        return results

"""Metadata-aware reranking and diversity selection."""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from datetime import date, datetime, timezone
from typing import Any, Dict, List, Optional, Sequence, Set

from .embeddings import cosine_similarity, tokenize
from .models import MetadataFilter, RetrievalResult


def _clamp01(value: Any) -> float:
    try:
        return max(0.0, min(1.0, float(value)))
    except (TypeError, ValueError):
        return 0.0


def _parse_date(value: Any) -> Optional[datetime]:
    """Parse metadata date values (datetime, date, ISO string) to naive UTC."""
    if value is None:
        return None
    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, date):
        dt = datetime(value.year, value.month, value.day)
    elif isinstance(value, str):
        text = value.strip()
        try:
            dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        except ValueError:
            return None
    else:
        return None
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt


@dataclass
class RankingConfig:
    """Weights for the composite metadata-aware ranking score.

    The final score is a weighted sum of:

    * **semantic**    - dense/BM25 fusion score (min-max normalized)
    * **keyword**     - lexical overlap between query and chunk
    * **recency**     - exponential decay over ``created_at`` age
    * **authority**   - the chunk's ``importance`` (0..1) metadata
    * **metadata**    - overlap between query terms and metadata values
    """

    semantic_weight: float = 0.50
    keyword_weight: float = 0.20
    recency_weight: float = 0.10
    authority_weight: float = 0.10
    metadata_match_weight: float = 0.10
    recency_half_life_days: float = 365.0

    def __post_init__(self) -> None:
        total = (
            self.semantic_weight
            + self.keyword_weight
            + self.recency_weight
            + self.authority_weight
            + self.metadata_match_weight
        )
        if total <= 0.0:
            raise ValueError("ranking weights must sum to a positive value")


class MetadataAwareReranker:
    """Re-orders candidate chunks by fusing retrieval scores with metadata
    signals so that, e.g., fresher or higher-authority documents win ties.
    """

    def __init__(self, config: Optional[RankingConfig] = None) -> None:
        self.config = config or RankingConfig()

    def rerank(
        self,
        query: str,
        candidates: Sequence[RetrievalResult],
        metadata_filter: Optional[MetadataFilter] = None,
        k: Optional[int] = None,
    ) -> List[RetrievalResult]:
        if not candidates:
            return []
        q_terms = set(tokenize(query))
        cfg = self.config

        # Min-max normalize the semantic scores within this candidate set so
        # they are comparable to the 0..1 metadata signals.
        raw_sem = [_clamp01(c.score) for c in candidates]
        lo, hi = min(raw_sem), max(raw_sem)

        def norm_sem(s: float) -> float:
            if hi > lo:
                return (s - lo) / (hi - lo)
            return 1.0 if hi > 0.0 else 0.0

        scored: List[tuple] = []
        for cand, sem in zip(candidates, raw_sem):
            score = (
                cfg.semantic_weight * norm_sem(sem)
                + cfg.keyword_weight * self._keyword_overlap(q_terms, cand.text)
                + cfg.recency_weight * self._recency_score(cand.metadata)
                + cfg.authority_weight * _clamp01(cand.metadata.get("importance", 0.5))
                + cfg.metadata_match_weight * self._metadata_match_score(q_terms, cand.metadata)
            )
            scored.append((score, cand))

        scored.sort(key=lambda t: t[0], reverse=True)
        if k is None:
            k = len(scored)

        out: List[RetrievalResult] = []
        for rank, (score, cand) in enumerate(scored[:k]):
            cand.score = float(score)
            cand.rank = rank
            out.append(cand)
        return out

    # ------------------------------------------------------------------ #
    @staticmethod
    def _keyword_overlap(q_terms: Set[str], text: str) -> float:
        if not q_terms:
            return 0.0
        text_terms = set(tokenize(text))
        return len(q_terms & text_terms) / len(q_terms)

    @staticmethod
    def _metadata_match_score(q_terms: Set[str], metadata: Dict[str, Any]) -> float:
        """Fraction of query terms that appear anywhere in the metadata."""
        if not q_terms:
            return 0.0
        hay = " ".join(
            str(v) for key, v in metadata.items()
            if key != "doc_id" and v is not None
        )
        hay_terms = set(tokenize(hay))
        return len(q_terms & hay_terms) / len(q_terms)

    def _recency_score(self, metadata: Dict[str, Any]) -> float:
        dt = _parse_date(metadata.get("created_at"))
        if dt is None:
            return 0.5  # neutral when no date is available
        days = max(0.0, (datetime.now() - dt).total_seconds() / 86400.0)
        return math.exp(-days / self.config.recency_half_life_days)


def mmr_select(
    candidates: Sequence[RetrievalResult],
    k: int,
    lambda_mult: float = 0.7,
) -> List[RetrievalResult]:
    """Maximal Marginal Relevance: trade relevance for diversity.

    ``lambda_mult=1.0`` keeps pure relevance; lower values increase
    diversity of the selected set.
    """
    if k <= 0 or not candidates:
        return []
    selected: List[RetrievalResult] = []
    remaining: List[RetrievalResult] = list(candidates)

    while len(selected) < k and remaining:
        best_i = 0
        best_val = float("-inf")
        for i, cand in enumerate(remaining):
            relevance = cand.score
            if selected:
                max_sim = max(_pair_sim(cand, s) for s in selected)
            else:
                max_sim = 0.0
            value = lambda_mult * relevance - (1.0 - lambda_mult) * max_sim
            if value > best_val:
                best_val = value
                best_i = i
        selected.append(remaining.pop(best_i))
    return selected


def _pair_sim(a: RetrievalResult, b: RetrievalResult) -> float:
    if a.embedding is not None and b.embedding is not None:
        return cosine_similarity(a.embedding, b.embedding)
    return 0.0

"""Unit tests for metadata filtering."""

import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from rag.models import Condition, FilterOperator, MetadataFilter


class TestConditions(unittest.TestCase):
    def setUp(self):
        self.meta = {
            "source": "TechDaily",
            "category": "ai",
            "importance": 0.8,
            "created_at": "2024-11-01",
            "tags": ["ai", "llm"],
            "author": "Ada Lin",
        }

    def test_eq_case_insensitive(self):
        self.assertTrue(Condition("category", FilterOperator.EQ, "AI").matches(self.meta))
        self.assertFalse(Condition("category", FilterOperator.EQ, "finance").matches(self.meta))

    def test_ne(self):
        self.assertTrue(Condition("source", FilterOperator.NE, "FinanceWire").matches(self.meta))
        self.assertFalse(Condition("source", FilterOperator.NE, "TechDaily").matches(self.meta))

    def test_date_ordering(self):
        self.assertTrue(Condition("created_at", FilterOperator.GTE, "2024-10-01").matches(self.meta))
        self.assertTrue(Condition("created_at", FilterOperator.GT, "2024-10-31T23:59:59").matches(self.meta))
        self.assertFalse(Condition("created_at", FilterOperator.LTE, "2024-10-01").matches(self.meta))

    def test_in_and_nin(self):
        self.assertTrue(Condition("source", FilterOperator.IN, ["TechDaily", "FinanceWire"]).matches(self.meta))
        self.assertFalse(Condition("source", FilterOperator.IN, ["FinanceWire"]).matches(self.meta))
        self.assertTrue(Condition("source", FilterOperator.NIN, ["FinanceWire", "HealthToday"]).matches(self.meta))

    def test_contains_list_and_substring(self):
        self.assertTrue(Condition("tags", FilterOperator.CONTAINS, "llm").matches(self.meta))
        self.assertFalse(Condition("tags", FilterOperator.CONTAINS, "crypto").matches(self.meta))
        self.assertTrue(Condition("title", FilterOperator.CONTAINS, "Anything").matches(
            {"title": "Anything goes here"}
        ))

    def test_exists(self):
        self.assertTrue(Condition("author", FilterOperator.EXISTS).matches(self.meta))
        self.assertFalse(Condition("department", FilterOperator.EXISTS).matches(self.meta))
        self.assertFalse(Condition("author", FilterOperator.EXISTS).matches({"author": ""}))

    def test_missing_key(self):
        self.assertFalse(Condition("missing", FilterOperator.EQ, "x").matches(self.meta))
        self.assertFalse(Condition("missing", FilterOperator.GT, 0).matches(self.meta))

    def test_numeric_ordering(self):
        self.assertTrue(Condition("importance", FilterOperator.GTE, 0.8).matches(self.meta))
        self.assertFalse(Condition("importance", FilterOperator.LT, 0.5).matches(self.meta))


class TestMetadataFilter(unittest.TestCase):
    def test_from_dict_equality(self):
        f = MetadataFilter.from_dict({"category": "ai", "source": "TechDaily"})
        self.assertTrue(f.matches({"category": "ai", "source": "TechDaily"}))
        self.assertFalse(f.matches({"category": "ai", "source": "FinanceWire"}))

    def test_from_dict_operator_and_date(self):
        f = MetadataFilter.from_dict({
            "source": {"in": ["TechDaily", "FinanceWire"]},
            "created_at": {"gte": "2024-01-01"},
        })
        self.assertTrue(f.matches({"source": "FinanceWire", "created_at": "2024-06-01"}))
        self.assertFalse(f.matches({"source": "FinanceWire", "created_at": "2023-12-31"}))

    def test_from_dict_none_means_exists(self):
        f = MetadataFilter.from_dict({"author": None})
        self.assertTrue(f.matches({"author": "Ada Lin"}))
        self.assertFalse(f.matches({}))

    def test_unknown_operator_raises(self):
        with self.assertRaises(ValueError):
            MetadataFilter.from_dict({"source": {"between": ["a", "b"]}})

    def test_or_groups(self):
        f = MetadataFilter(
            [Condition("category", FilterOperator.EQ, "finance")],
            or_groups=[
                [Condition("source", FilterOperator.EQ, "FinanceWire"),
                 Condition("source", FilterOperator.EQ, "CryptoTimes")],
            ],
        )
        self.assertTrue(f.matches({"category": "finance", "source": "CryptoTimes"}))
        self.assertTrue(f.matches({"category": "finance", "source": "FinanceWire"}))
        self.assertFalse(f.matches({"category": "finance", "source": "TechDaily"}))

    def test_empty_filter(self):
        self.assertTrue(MetadataFilter().matches({}))
        self.assertTrue(MetadataFilter().empty())


if __name__ == "__main__":
    unittest.main()

