    "author": "Ada Lin",
}


class TestConditions(unittest.TestCase):
    def test_eq_case_insensitive(self):
        self.assertTrue(Condition("category", FilterOperator.EQ, "AI").matches(META))
        self.assertFalse(Condition("category", FilterOperator.EQ, "finance").matches(META))

    def test_ne(self):
        self.assertTrue(Condition("source", FilterOperator.NE, "FinanceWire").matches(META))

    def test_date_ordering(self):
        self.assertTrue(Condition("created_at", FilterOperator.GTE, "2024-10-01").matches(META))
        self.assertTrue(Condition("created_at", FilterOperator.GT, "2024-10-31T23:59:59").matches(META))
        self.assertFalse(Condition("created_at", FilterOperator.LTE, "2024-10-01").matches(META))

    def test_in_and_nin(self):
        self.assertTrue(Condition("source", FilterOperator.IN, ["TechDaily", "FinanceWire"]).matches(META))
        self.assertFalse(Condition("source", FilterOperator.IN, ["FinanceWire"]).matches(META))
        self.assertTrue(Condition("source", FilterOperator.NIN, ["FinanceWire", "HealthToday"]).matches(META))

    def test_contains_list_and_substring(self):
        self.assertTrue(Condition("tags", FilterOperator.CONTAINS, "llm").matches(META))
        self.assertFalse(Condition("tags", FilterOperator.CONTAINS, "crypto").matches(META))
        self.assertTrue(Condition("title", FilterOperator.CONTAINS, "Anything").matches(
            {"title": "Anything goes here"}
        ))

    def test_exists(self):
        self.assertTrue(Condition("author", FilterOperator.EXISTS).matches(META))
        self.assertFalse(Condition("department", FilterOperator.EXISTS).matches(META))
        self.assertFalse(Condition("author", FilterOperator.EXISTS).matches({"author": ""}))

    def test_missing_key(self):
        self.assertFalse(Condition("missing", FilterOperator.EQ, "x").matches(META))
        self.assertFalse(Condition("missing", FilterOperator.GT, 0).matches(META))

    def test_numeric_ordering(self):
        self.assertTrue(Condition("importance", FilterOperator.GTE, 0.8).matches(META))
        self.assertFalse(Condition("importance", FilterOperator.LT, 0.5).matches(META))


